$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$helper = Decode ""
$wrapper = Decode ""

$routePath = Join-Path $root "app\api\provider\jobs\route.ts"
$helperPath = Join-Path $root "lib\provider-jobs-live-revalidation.ts"
$groupRoute = Join-Path $root "app\api\booking-groups\[id]\route.ts"
$migration96 = Join-Path $root "supabase\migrations\20260812223200_klyx_group_atomic_live_coverage_12_96.sql"

foreach ($path in @($routePath, $groupRoute, $migration96)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.08 : fichier requis introuvable : $path"
    }
}

$route = [System.IO.File]::ReadAllText($routePath)
$group = [System.IO.File]::ReadAllText($groupRoute)
$sql96 = [System.IO.File]::ReadAllText($migration96)

if (-not $route.Contains("KLYX_PROVIDER_MULTI_JOBS_API_12_93")) {
    throw "13.08 : Provider Jobs 12.93 introuvable."
}

if (-not $group.Contains("KLYX_GROUP_PROVIDER_ACCEPT_RECOVERY_13_07")) {
    throw "13.08 : KLYX 13.07 introuvable."
}

if (-not $sql96.Contains("klyx_group_live_coverage_check")) {
    throw "13.08 : RPC live coverage 12.96 introuvable."
}

if ($route.Contains("KLYX_PROVIDER_JOBS_LIVE_ROUTE_13_08")) {
    Write-Host "KLYX 13.08 deja applique."
    exit 0
}

$pattern = 'export\s+async\s+function\s+GET\s*\('
$matches = [regex]::Matches($route, $pattern)

if ($matches.Count -ne 1) {
    throw "13.08 : GET Provider Jobs ambigu. Nombre trouve : $($matches.Count)"
}

$match = $matches[0]
$replacement = "async function klyxProviderJobsBeforeLiveEligibility13_08("

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $routePath -Destination ($routePath + ".bak-13-08-" + $timestamp) -Force

if (Test-Path -LiteralPath $helperPath) {
    Copy-Item -LiteralPath $helperPath -Destination ($helperPath + ".bak-13-08-" + $timestamp) -Force
}

$route = $route.Remove($match.Index, $match.Length).Insert($match.Index, $replacement)

$route = $route.TrimEnd() + "`r`n`r`n" + $wrapper.Trim() + "`r`n"

[System.IO.File]::WriteAllText($helperPath, $helper, $utf8)
[System.IO.File]::WriteAllText($routePath, $route, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.08 APPLIQUE"
Write-Host "======================================"
Write-Host "Provider Jobs : LIVE-AWARE"
Write-Host "Simple missions : INCHANGEES"
Write-Host "Multi-slot : N/N REVALIDE"
Write-Host "Mission stale : MASQUEE"
Write-Host "Candidate cache : RESYNCHRONISE"
Write-Host "Offre automatique : NON"
Write-Host "Booking automatique : NON"
Write-Host "Paiement automatique : NON"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
